[CmdletBinding(DefaultParameterSetName='Result')]
param(
 [Parameter(Mandatory,ParameterSetName='Result')][string]$ResultPath,
 [Parameter(Mandatory,ParameterSetName='Probe')][string]$RuntimeLogPath,
 [Parameter(Mandatory,ParameterSetName='Probe')][string]$BmpPath,
 [Parameter(Mandatory,ParameterSetName='Probe')][switch]$ProbeOnly,
 [Parameter(ParameterSetName='Probe')][switch]$AuditOnly
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$repoRoot=(Resolve-Path -LiteralPath (Join-Path $PSScriptRoot '..')).Path
$titleVerifier=Join-Path $PSScriptRoot 'verify-render-path-smoke.ps1'
$gameVerifier=Join-Path $PSScriptRoot 'verify-game-manifest.ps1'
$canonicalGame=Join-Path $repoRoot 'private/game'
$canonicalBuild=Join-Path $repoRoot 'out/build/win-amd64-relwithdebinfo'
$artifactNames=@('mcla.exe','rexruntimerd.dll','TracyClientrd.dll','rexgpu-xenosrd.dll')
$utf8=[Text.UTF8Encoding]::new($false)
$hashPattern='^[0-9A-F]{64}$'

function Assert-ExactProperties {param([object]$Value,[string[]]$Expected,[string]$Description)$a=@($Value.PSObject.Properties.Name|Sort-Object);$w=@($Expected|Sort-Object);if($a.Count-ne$w.Count){throw "$Description has missing or unknown properties."};for($i=0;$i-lt$w.Count;$i++){if($a[$i]-cne$w[$i]){throw "$Description has missing or unknown properties."}}}
function Assert-JsonTypes {param([object]$Value,[string[]]$Booleans=@(),[string[]]$Integers=@(),[string[]]$Strings=@(),[string]$Description)foreach($n in $Booleans){if($Value.PSObject.Properties[$n].Value-isnot[bool]){throw "$Description '$n' must be a JSON boolean."}};foreach($n in $Integers){$v=$Value.PSObject.Properties[$n].Value;if($v-isnot[int32]-and$v-isnot[int64]-and$v-isnot[uint32]-and$v-isnot[uint64]-and$v-isnot[int16]-and$v-isnot[uint16]-and$v-isnot[byte]-and$v-isnot[sbyte]){throw "$Description '$n' must be a JSON integer."}};foreach($n in $Strings){if($Value.PSObject.Properties[$n].Value-isnot[string]){throw "$Description '$n' must be a JSON string."}}}
function Assert-ContainedNonReparsePath {param([string]$Path,[string]$Description)$full=[IO.Path]::GetFullPath($Path);$prefix=$repoRoot.TrimEnd('\')+'\';if(-not$full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw "$Description must stay inside the repository."};$current=$repoRoot;foreach($part in @($full.Substring($prefix.Length).Split('\')|Where-Object{$_.Length})){$current=Join-Path $current $part;if(-not(Test-Path -LiteralPath $current)){throw "$Description component is missing."};if((Get-Item $current -Force).Attributes-band[IO.FileAttributes]::ReparsePoint){throw "$Description traverses a reparse point."}};$full}
function Assert-ExactChildren {param([string]$Root,[string[]]$Expected,[string]$Description)$a=@((Get-ChildItem $Root -Force|Sort-Object Name).Name);$w=@($Expected|Sort-Object);if($a.Count-ne$w.Count){throw "$Description has missing or extra children."};for($i=0;$i-lt$w.Count;$i++){if($a[$i]-cne$w[$i]){throw "$Description has incorrectly named children."}}}
function Get-TreeSnapshot {param([string]$Root)$items=@(Get-ChildItem $Root -Recurse -Force);$entries=@();$files=@($items|Where-Object{-not$_.PSIsContainer}|Sort-Object FullName);foreach($i in @((Get-Item $Root -Force))+$items){if($i.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Evidence or source tree contains a reparse point.'}};foreach($d in @($items|Where-Object PSIsContainer|Sort-Object FullName)){$entries+=[ordered]@{kind='directory';path=$d.FullName.Substring($Root.Length).TrimStart('\').Replace('\','/')}};foreach($f in $files){$entries+=[ordered]@{kind='file';path=$f.FullName.Substring($Root.Length).TrimStart('\').Replace('\','/');length=$f.Length;sha256=(Get-FileHash $f.FullName -Algorithm SHA256).Hash}};$json=ConvertTo-Json -InputObject @($entries) -Depth 4 -Compress;$sha=[Security.Cryptography.SHA256]::Create();try{$hash=-join($sha.ComputeHash($utf8.GetBytes($json))|ForEach-Object{$_.ToString('X2')})}finally{$sha.Dispose()};$bytes=0L;foreach($f in $files){$bytes+=[long]$f.Length};[pscustomobject]@{Hash=$hash;FileCount=$files.Count;DirectoryCount=@($items|Where-Object PSIsContainer).Count;Bytes=$bytes}}
function Get-RuntimeLogSet {param([string]$CurrentLogPath)if((Split-Path -Leaf $CurrentLogPath)-cne'mcla.log'){throw 'Current runtime log must be named mcla.log.'};$files=@(Get-ChildItem (Split-Path -Parent $CurrentLogPath) -File -Force -Filter 'mcla*.log');if($files.Count-lt1-or$files.Count-gt16){throw 'Runtime log set must contain 1-16 files.'};$current=@($files|Where-Object{$_.Name-ceq'mcla.log'});if($current.Count-ne1){throw 'Runtime log set requires exactly one mcla.log.'};$rot=@();foreach($f in $files){if($f.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Runtime log is a reparse point.'};if($f.Name-ceq'mcla.log'){continue};$m=[regex]::Match($f.Name,'^mcla\.([1-9][0-9]*)\.log$');if(-not$m.Success){throw 'Malformed runtime log rotation name.'};$rot+=[pscustomobject]@{N=[int]$m.Groups[1].Value;F=$f}};$ids=@($rot|ForEach-Object{$_.N}|Sort-Object);for($i=0;$i-lt$ids.Count;$i++){if($ids[$i]-ne$i+1-or$ids[$i]-gt15){throw 'Runtime log rotations are not contiguous.'}};$ordered=@($rot|Sort-Object N -Descending|ForEach-Object{$_.F})+$current;$manifest=@();$parts=@();$bytes=0L;$previous=[datetime]::MinValue;foreach($f in $ordered){if($f.Length-gt8388608-or$f.LastWriteTimeUtc-lt$previous){throw 'Runtime log size or chronology failed.'};$previous=$f.LastWriteTimeUtc;$bytes+=$f.Length;if($bytes-gt100663296){throw 'Runtime logs exceed 96 MiB.'};$manifest+=[ordered]@{name=$f.Name;bytes=$f.Length;sha256=(Get-FileHash $f.FullName -Algorithm SHA256).Hash};$parts+=[IO.File]::ReadAllText($f.FullName)};$json=ConvertTo-Json -InputObject @($manifest) -Depth 3 -Compress;$sha=[Security.Cryptography.SHA256]::Create();try{$hash=-join($sha.ComputeHash($utf8.GetBytes($json))|ForEach-Object{$_.ToString('X2')})}finally{$sha.Dispose()};[pscustomobject]@{Files=@($manifest);Count=$manifest.Count;Bytes=$bytes;Hash=$hash;Text=($parts-join[Environment]::NewLine)}}
function Get-GameIdentity {$root=Assert-ContainedNonReparsePath $canonicalGame 'Canonical game tree';$manifest=Assert-ContainedNonReparsePath (Join-Path $repoRoot 'private/game-manifest.json') 'Canonical game manifest';$tree=Get-TreeSnapshot $root;$v=&$gameVerifier -GamePath $root -ManifestPath $manifest -VerifyHashes;[pscustomobject]@{file_count=$v.FileCount;payload_bytes=$v.PayloadBytes;hashes_verified=$v.HashesVerified;manifest_sha256=(Get-FileHash $manifest -Algorithm SHA256).Hash;tree_sha256=$tree.Hash;tree_file_count=$tree.FileCount;tree_directory_count=$tree.DirectoryCount;tree_bytes=$tree.Bytes}}
function Get-Artifacts {@($artifactNames|ForEach-Object{$p=Assert-ContainedNonReparsePath (Join-Path $canonicalBuild $_) "Artifact $_";[pscustomobject]@{name=$_;sha256=(Get-FileHash $p -Algorithm SHA256).Hash}})}
function Get-ExactProcesses {$exe=[IO.Path]::GetFullPath((Join-Path $canonicalBuild 'mcla.exe'));@((Get-Process mcla -ErrorAction SilentlyContinue)|Where-Object{try{[string]::Equals($_.Path,$exe,[StringComparison]::OrdinalIgnoreCase)}catch{$false}})}

function Assert-StaticContract {
 $generated=Get-ChildItem (Join-Path $repoRoot 'generated/default') -Filter 'mcla_recomp.*.cpp' -File;$expected=[ordered]@{XamInputGetCapabilities=2;XamInputGetState=1;XamInputSetState=1;XamInputGetKeystrokeEx=1};foreach($name in $expected.Keys){$count=0;foreach($f in $generated){$count+=[regex]::Matches([IO.File]::ReadAllText($f.FullName),[regex]::Escape("__imp__$name(ctx, base)")).Count};if($count-ne$expected[$name]){throw "Generated import count for $name changed."}}
 $xam=[IO.File]::ReadAllText((Join-Path $repoRoot 'third_party/rexglue-sdk/src/kernel/xam/xam_input.cpp'));foreach($name in $expected.Keys){if($xam-notmatch"REX_EXPORT\(__imp__$name,"){throw "$name is not a concrete SDK export."};if($xam-match"REX_EXPORT_STUB\(__imp__$name\)"){throw "$name regressed to a stub."}}
 $sdl=[IO.File]::ReadAllText((Join-Path $repoRoot 'third_party/rexglue-sdk/src/input/sdl/sdl_input_driver.cpp'));foreach($needle in @('SDL_GAMEPAD_BUTTON_SOUTH','X_INPUT_GAMEPAD_A','RecordInputSlotDeviceAssigned')){if(-not$sdl.Contains($needle)){throw "SDL slot contract missing '$needle'."}}
 $header=Join-Path $repoRoot 'third_party/rexglue-sdk/include/rex/input/sdl/input_slot_audit.h';if(-not(Test-Path $header)-or-not([IO.File]::ReadAllText($header).Contains('ArmInputSlotAudit'))){throw 'Input slot audit public API is missing.'}
 $unit=Join-Path $repoRoot 'third_party/rexglue-sdk/tests/unit/input/sdl_slot_mapping_test.cpp';$cmake=Join-Path $repoRoot 'third_party/rexglue-sdk/tests/unit/CMakeLists.txt';if(-not(Test-Path $unit)-or-not([IO.File]::ReadAllText($unit).Contains('[input][sdl][slot]'))-or-not([IO.File]::ReadAllText($cmake).Contains('input/sdl_slot_mapping_test.cpp'))){throw 'Focused SDL slot tests are missing or unregistered.'}
 $app=[IO.File]::ReadAllText((Join-Path $repoRoot 'src/mcla_app.cpp'));if(-not$app.Contains('rex::input::sdl::ArmInputSlotAudit("title")')){throw 'Title checkpoint does not arm input audit.'}
}

function Get-InputProbe {param([string]$LogPath,[string]$FramePath,[switch]$SkipTitle)
 $logPathResolved=Assert-ContainedNonReparsePath $LogPath 'Runtime log';$frame=Assert-ContainedNonReparsePath $FramePath 'Capture BMP';$title=$null;if(-not$SkipTitle){$title=&$titleVerifier -ProbeOnly -RuntimeLogPath $logPathResolved -BmpPath $frame};$set=Get-RuntimeLogSet $logPathResolved;$log=$set.Text
 $launch=[regex]::Matches($log,[regex]::Escape('KernelState: Preparing module launch...'));$capture=[regex]::Matches($log,'(?m)^.*MCLA graphics: nontrivial guest frame captured .*$');if($launch.Count-ne1-or$capture.Count-ne1){throw 'Input route requires exactly one module launch and title capture marker.'}
 $patterns=[ordered]@{
 Config='(?m)^.*SDL_INPUT_SLOT_AUDIT_CONFIG v=1 enabled=1 expected_slot=0\r?$'
 Device='(?m)^.*SDL_INPUT_SLOT_AUDIT_DEVICE v=1 event=assigned slot=0 active_devices=1\r?$'
 Arm='(?m)^.*SDL_INPUT_SLOT_AUDIT_ARM v=1 phase=title status=READY active_devices=1 slot_mask=1 neutral=1\r?$'
 Sdl='(?m)^.*SDL_INPUT_SLOT_AUDIT_SDL_EDGE v=1 control=A edge=(?<edge>down|up) slot=0 source_seq=(?<seq>[12])\r?$'
 Guest='(?m)^.*SDL_INPUT_SLOT_AUDIT_GUEST_STATE v=1 control=A edge=(?<edge>down|up) slot=0 result=00000000 source_seq=(?<seq>[12])\r?$'
 Summary='(?m)^.*SDL_INPUT_SLOT_AUDIT_SUMMARY v=1 phase=title status=PASS active_devices=1 slot_mask=1 query_mask=F success_mask=1 disconnected_mask=E sdl_down_seq=1 guest_down_seq=1 sdl_up_seq=2 guest_up_seq=2 removals=0 rejected=0 unexpected=0 failures=0 dropped_records=0\r?$'
 }
 $m=@{};foreach($k in $patterns.Keys){$m[$k]=[regex]::Matches($log,$patterns[$k])};foreach($k in 'Config','Device','Arm','Summary'){if($m[$k].Count-ne1){throw "Exactly one canonical $k input marker is required."}};if($m.Sdl.Count-ne2-or$m.Guest.Count-ne2){throw 'Exactly two SDL and two guest challenge edges are required.'}
 $sd=@($m.Sdl|Where-Object{$_.Groups['edge'].Value-eq'down'-and$_.Groups['seq'].Value-eq'1'});$su=@($m.Sdl|Where-Object{$_.Groups['edge'].Value-eq'up'-and$_.Groups['seq'].Value-eq'2'});$gd=@($m.Guest|Where-Object{$_.Groups['edge'].Value-eq'down'-and$_.Groups['seq'].Value-eq'1'});$gu=@($m.Guest|Where-Object{$_.Groups['edge'].Value-eq'up'-and$_.Groups['seq'].Value-eq'2'});if($sd.Count-ne1-or$su.Count-ne1-or$gd.Count-ne1-or$gu.Count-ne1){throw 'Challenge edges differ from canonical down/up sequence.'}
 if(-not($m.Config[0].Index-lt$m.Device[0].Index-and$m.Device[0].Index-lt$m.Arm[0].Index-and$launch[0].Index-lt$m.Arm[0].Index-and$m.Arm[0].Index-lt$capture[0].Index-and$capture[0].Index-lt$sd[0].Index-and$sd[0].Index-lt$gd[0].Index-and$gd[0].Index-lt$su[0].Index-and$su[0].Index-lt$gu[0].Index-and$gu[0].Index-lt$m.Summary[0].Index)){throw 'Input audit chronology is not causal.'}
 $all=[regex]::Matches($log,'(?m)^.*SDL_INPUT_SLOT_AUDIT_[A-Z_]+.*$');if($all.Count-ne8){throw 'Unknown, malformed, duplicate, rejected, removed, or failure input marker exists.'};if($log-match'(?im)^.*(?:SDL_INPUT_SLOT_AUDIT_.*(?:status=FAIL|event=(?:removed|rejected))|REX_EXPORT_STUB.*XamInput|XamInput.*unimplemented).*$'){throw 'Input audit contains a failure, removal, rejection, stub, or unimplemented marker.'}
 [pscustomobject]@{LogSet=$set;Title=$title;ConfigCount=1;DeviceCount=1;ArmCount=1;SdlEdgeCount=2;GuestEdgeCount=2;SummaryCount=1}
}

if(-not($PSCmdlet.ParameterSetName-eq'Probe'-and$AuditOnly)){Assert-StaticContract}
if($PSCmdlet.ParameterSetName-eq'Probe'){if(-not$ProbeOnly){throw 'Probe inputs require -ProbeOnly.'};Get-InputProbe $RuntimeLogPath $BmpPath -SkipTitle:$AuditOnly;return}
$resolved=Assert-ContainedNonReparsePath $ResultPath 'Result path';if((Split-Path -Leaf $resolved)-cne'result.json'){throw 'Result must be result.json.'};$json=[IO.File]::ReadAllText($resolved);if($json.Length-gt1048576){throw 'Result exceeds 1 MiB.'};foreach($p in @('(?i)[A-Z]:[\\/]','(?i)\\\\[^"\s]+[\\/]','(?i)(?:^|["\\/])private[\\/]','(?i)(?:controller_(?:name|guid|serial)|vendor|product)')){if($json-match$p){throw 'Sanitized result contains a private path or controller identity.'}};$r=$json|ConvertFrom-Json
$top=@('schema','task','decision','cycle_count','capture_timeout_seconds','first_frame_settle_seconds','hold_timeout_seconds','release_timeout_seconds','post_marker_dwell_milliseconds','exit_timeout_seconds','clean_build','game_identity','artifacts','cycles','all_write_roots_contained','no_surviving_processes','data_integrity_preserved','title_probe_passed','input_slot_probe_passed','operator_interaction_required')
Assert-ExactProperties $r $top 'M4-005 result';Assert-JsonTypes $r -Booleans @('all_write_roots_contained','no_surviving_processes','data_integrity_preserved','title_probe_passed','input_slot_probe_passed','operator_interaction_required') -Integers @('schema','cycle_count','capture_timeout_seconds','first_frame_settle_seconds','hold_timeout_seconds','release_timeout_seconds','post_marker_dwell_milliseconds','exit_timeout_seconds') -Strings @('task','decision') -Description 'M4-005 result';if($r.schema-ne1-or$r.task-cne'M4-005'-or$r.decision-cne'single-sdl-controller-slot0'-or$r.cycle_count-ne1-or$r.capture_timeout_seconds-ne60-or$r.first_frame_settle_seconds-ne35-or$r.hold_timeout_seconds-ne30-or$r.release_timeout_seconds-ne30-or$r.post_marker_dwell_milliseconds-ne2000-or$r.exit_timeout_seconds-ne10-or-not$r.operator_interaction_required){throw 'M4-005 header is noncanonical.'}
$buildFields=@('sdk_install_performed','sdk_install_success','sdk_install_exit_code','sdk_install_duration_milliseconds','sdk_install_log_sha256','sdk_input_test_performed','sdk_input_test_success','sdk_input_test_exit_code','sdk_input_test_duration_milliseconds','sdk_input_test_cases','sdk_input_test_assertions','sdk_input_test_log_sha256','sdk_input_test_executable_sha256','app_clean_build_performed','app_clean_build_success','app_clean_build_exit_code','app_clean_build_duration_milliseconds','app_clean_build_log_sha256','executable_sha256');Assert-ExactProperties $r.clean_build $buildFields 'Clean build';Assert-JsonTypes $r.clean_build -Booleans @('sdk_install_performed','sdk_install_success','sdk_input_test_performed','sdk_input_test_success','app_clean_build_performed','app_clean_build_success') -Integers @('sdk_install_exit_code','sdk_install_duration_milliseconds','sdk_input_test_exit_code','sdk_input_test_duration_milliseconds','sdk_input_test_cases','sdk_input_test_assertions','app_clean_build_exit_code','app_clean_build_duration_milliseconds') -Strings @('sdk_install_log_sha256','sdk_input_test_log_sha256','sdk_input_test_executable_sha256','app_clean_build_log_sha256','executable_sha256') -Description 'Clean build';if(-not$r.clean_build.sdk_install_performed-or-not$r.clean_build.sdk_install_success-or$r.clean_build.sdk_install_exit_code-ne0-or-not$r.clean_build.sdk_input_test_performed-or-not$r.clean_build.sdk_input_test_success-or$r.clean_build.sdk_input_test_exit_code-ne0-or$r.clean_build.sdk_input_test_cases-ne5-or$r.clean_build.sdk_input_test_assertions-ne12-or-not$r.clean_build.app_clean_build_performed-or-not$r.clean_build.app_clean_build_success-or$r.clean_build.app_clean_build_exit_code-ne0){throw 'Clean SDK/input-test/app build contract failed.'};foreach($n in @($buildFields|Where-Object{$_-like'*sha256'})){if($r.clean_build.$n-notmatch$hashPattern){throw "Invalid clean-build hash '$n'."}}
$identityFields=@('file_count','payload_bytes','hashes_verified','manifest_sha256','tree_sha256','tree_file_count','tree_directory_count','tree_bytes');Assert-ExactProperties $r.game_identity @('before','after') 'Game identity';foreach($phase in 'before','after'){Assert-ExactProperties $r.game_identity.$phase $identityFields "Game identity $phase"};foreach($f in $identityFields){if($r.game_identity.before.$f-ne$r.game_identity.after.$f){throw "Game identity '$f' drifted."}}
Assert-ExactProperties $r.artifacts @('before','after') 'Artifacts';foreach($phase in 'before','after'){$a=@($r.artifacts.$phase);if($a.Count-ne4){throw 'Four artifacts required.'};for($i=0;$i-lt4;$i++){Assert-ExactProperties $a[$i] @('name','sha256') 'Artifact';if($a[$i].name-cne$artifactNames[$i]-or$a[$i].sha256-notmatch$hashPattern-or$a[$i].sha256-ne$r.artifacts.before[$i].sha256){throw 'Artifact identity drifted.'}}}
$runRoot=Split-Path -Parent $resolved;$expected=[IO.Path]::GetFullPath((Join-Path $repoRoot 'private/evidence/M4-005'));if(-not[string]::Equals((Split-Path -Parent $runRoot),$expected,[StringComparison]::OrdinalIgnoreCase)){throw 'Run root must be an immediate M4-005 evidence child.'};Assert-ExactChildren $runRoot @('result.json','runs','sdk-install.log','sdk-input-test.log','relwithdebinfo-clean-build.log') 'Run root';$runs=Join-Path $runRoot 'runs';Assert-ExactChildren $runs @('01') 'Runs root'
$cycleFields=@('index','capture_elapsed_milliseconds','hold_elapsed_milliseconds','release_elapsed_milliseconds','dwell_elapsed_milliseconds','exit_elapsed_milliseconds','exit_code','hold_prompted','release_prompted','close_requested','harness_force_cleanup','process_signal_confirmed','process_cleanup_confirmed','runtime_logs','runtime_log_file_count','runtime_log_bytes','runtime_log_set_sha256','capture_relative_path','capture_sha256','capture_bytes','logo_edge_correlation_ppm','press_edge_correlation_ppm','resolve_calls','draw_issued','audit_config_count','audit_device_count','audit_arm_count','audit_sdl_edge_count','audit_guest_edge_count','audit_summary_count','user_tree_sha256','cache_tree_sha256','cycle_tree_sha256','user_file_count','cache_file_count','user_bytes','cache_bytes');$cycles=@($r.cycles);if($cycles.Count-ne1){throw 'Exactly one physical cycle required.'};$c=$cycles[0];Assert-ExactProperties $c $cycleFields 'Cycle 01';if($c.index-ne1-or$c.capture_elapsed_milliseconds-lt0-or$c.capture_elapsed_milliseconds-gt60000-or$c.hold_elapsed_milliseconds-lt0-or$c.hold_elapsed_milliseconds-gt30000-or$c.release_elapsed_milliseconds-lt0-or$c.release_elapsed_milliseconds-gt30000-or$c.dwell_elapsed_milliseconds-lt2000-or$c.exit_elapsed_milliseconds-lt0-or$c.exit_elapsed_milliseconds-gt10000-or$c.exit_code-ne0-or-not$c.hold_prompted-or-not$c.release_prompted-or-not$c.close_requested-or$c.harness_force_cleanup-or-not$c.process_signal_confirmed-or-not$c.process_cleanup_confirmed){throw 'Cycle process/interaction contract failed.'};$logs=@($c.runtime_logs);if($logs.Count-lt1-or$logs.Count-gt16-or$c.runtime_log_file_count-ne$logs.Count){throw 'Runtime log manifest cardinality failed.'};foreach($l in $logs){Assert-ExactProperties $l @('name','bytes','sha256') 'Runtime log';if($l.sha256-notmatch$hashPattern){throw 'Runtime log hash invalid.'}};$root=Join-Path $runs '01';Assert-ExactChildren $root (@('cache','user')+@($logs.name)) 'Cycle root';$bmp=Join-Path $root 'user/mcla-first-frame.bmp';if($c.capture_relative_path-cne'runs/01/user/mcla-first-frame.bmp'-or@(Get-ChildItem $root -Recurse -File -Filter '*.bmp').Count-ne1){throw 'Capture topology is noncanonical.'};$p=Get-InputProbe (Join-Path $root 'mcla.log') $bmp;if($c.runtime_log_file_count-ne$p.LogSet.Count-or$c.runtime_log_bytes-ne$p.LogSet.Bytes-or$c.runtime_log_set_sha256-ne$p.LogSet.Hash-or$c.capture_sha256-ne$p.Title.Bmp.Sha256-or$c.capture_bytes-ne$p.Title.Bmp.Bytes-or$c.logo_edge_correlation_ppm-ne$p.Title.Roi.LogoCorrelationPpm-or$c.press_edge_correlation_ppm-ne$p.Title.Roi.PressCorrelationPpm-or$c.resolve_calls-ne$p.Title.Audit.ResolveCalls-or$c.draw_issued-ne$p.Title.Audit.DrawIssued-or$c.audit_config_count-ne1-or$c.audit_device_count-ne1-or$c.audit_arm_count-ne1-or$c.audit_sdl_edge_count-ne2-or$c.audit_guest_edge_count-ne2-or$c.audit_summary_count-ne1){throw 'Cycle aggregate does not match physical evidence.'};for($i=0;$i-lt$logs.Count;$i++){foreach($f in 'name','bytes','sha256'){if($logs[$i].$f-ne$p.LogSet.Files[$i].$f){throw 'Runtime log manifest mismatch.'}}};$u=Get-TreeSnapshot(Join-Path $root 'user');$k=Get-TreeSnapshot(Join-Path $root 'cache');$t=Get-TreeSnapshot $root;if($c.user_tree_sha256-ne$u.Hash-or$c.cache_tree_sha256-ne$k.Hash-or$c.cycle_tree_sha256-ne$t.Hash-or$c.user_file_count-ne$u.FileCount-or$c.cache_file_count-ne$k.FileCount-or$c.user_bytes-ne$u.Bytes-or$c.cache_bytes-ne$k.Bytes){throw 'Cycle tree aggregate mismatch.'}
foreach($f in 'all_write_roots_contained','no_surviving_processes','data_integrity_preserved','title_probe_passed','input_slot_probe_passed'){if(-not$r.$f){throw "Aggregate '$f' is false."}}
$sdkLog=Assert-ContainedNonReparsePath (Join-Path $runRoot 'sdk-install.log') 'SDK install log';$inputLog=Assert-ContainedNonReparsePath (Join-Path $runRoot 'sdk-input-test.log') 'SDK input test log';$appLog=Assert-ContainedNonReparsePath (Join-Path $runRoot 'relwithdebinfo-clean-build.log') 'App build log';$unitExe=Assert-ContainedNonReparsePath (Join-Path $repoRoot 'third_party/rexglue-sdk/out/win-amd64/RelWithDebInfo/unit_tests.exe') 'SDK unit executable';if((Get-FileHash $sdkLog -Algorithm SHA256).Hash-ne$r.clean_build.sdk_install_log_sha256-or(Get-FileHash $inputLog -Algorithm SHA256).Hash-ne$r.clean_build.sdk_input_test_log_sha256-or(Get-FileHash $appLog -Algorithm SHA256).Hash-ne$r.clean_build.app_clean_build_log_sha256-or(Get-FileHash $unitExe -Algorithm SHA256).Hash-ne$r.clean_build.sdk_input_test_executable_sha256){throw 'Clean build/input test evidence is not physically bound.'};$testText=[IO.File]::ReadAllText($inputLog);if($testText-notmatch"All tests passed \($($r.clean_build.sdk_input_test_assertions) assertions in $($r.clean_build.sdk_input_test_cases) test case(?:s)?\)"){throw 'Focused input-test totals do not match the physical log.'}
$physicalGame=Get-GameIdentity;foreach($f in $identityFields){if($r.game_identity.after.$f-ne$physicalGame.$f){throw "Physical game identity '$f' differs."}};$physicalArtifacts=Get-Artifacts;for($i=0;$i-lt4;$i++){if($r.artifacts.after[$i].sha256-ne$physicalArtifacts[$i].sha256){throw 'Physical artifact differs.'}};if($r.clean_build.executable_sha256-ne$physicalArtifacts[0].sha256){throw 'Clean-build executable hash is not current.'};if(@(Get-ExactProcesses).Count){throw 'Exact MCLA process survived.'}
[pscustomobject]@{Passed=$true;Decision='single-sdl-controller-slot0';Cycles=1;PhysicalTitleProbes=1;InputSlotProbes=1;OperatorInteractionRequired=$true}
